import{t as e}from"./utils-COoNfFoj.js";var t={slug:`cory-weigel`,influencerName:`Cory Weigel`,influencerHandle:`@coryjweigel`,influencerAvatarUrl:`${e}/cory-weigel-avatar.jpg`,heroDescription:`I built this acquisition copilot to streamline the complex business buying process from hours to minutes, helping existing entrepreneurs new to acquisitions navigate deals strategically, confidently, and at scale.`,assetTitle:`Acquisition Command Center`,screenshotUrl:`${e}/cory-weigel.png`,remixUrl:`https://www.perplexity.ai/computer/a/atlas-acquisition-platform-6tOIjcfqQvWxfuLPNw5NJg`,promptTitle:`Try Cory's prompt`,promptText:`Build a highly interactive, investor-grade acquisition analysis platform — not a static report — that walks me end-to-end: a discovery wizard (my business + buy box), an AI targeting engine that recommends what to buy and pulls real on-market broker listings sorted by fit (plus manual search and an off-market path), editable target financials with add-backs, qualitative deal intel, projections, a plain-English verdict, and a slide-deck builder. Use a sleek "command center" aesthetic — obsidian hero with a subtle grid and a sweeping LED accent line, cyan-to-blue gradient highlights, amber CTAs, Space Grotesk headlines, JetBrains Mono numerics — with friendly, second-person copy ("Should you buy this? Here's our honest answer.") so it feels welcoming, not corporate.`};export{t as default};
